const $=s=>document.querySelector(s);const $$=s=>document.querySelectorAll(s);
function getCard(id){if(typeof id!=='string')return CARD_DB[id];let up=id.endsWith('+'),c=CARD_DB[up?id.slice(0,-1):id];if(!c)return c;if(up&&c.cost>0)c=Object.assign({},c,{name:c.name+' ⁺',cost:c.cost-1});return c}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
// ── Seeded RNG (mulberry32): детерминизм забега, воспроизводимость, симуляции ──
const RNG_STATE={s:1};
function srand(n){RNG_STATE.s=(n>>>0)||1}
function rng(){RNG_STATE.s|=0;RNG_STATE.s=RNG_STATE.s+0x6D2B79F5|0;let t=Math.imul(RNG_STATE.s^RNG_STATE.s>>>15,1|RNG_STATE.s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}

let G=null,B=null;
const NET={active:false,role:null,id:Math.random().toString(36).slice(2),room:null,ref:null,applying:false,phase:'menu'};

function hero(name,kind){let mh=kind===1?72:kind===2?62:58;return{name,kind,maxHp:mh,hp:mh,position:kind===1?'front':'back',block:0,minions:0,minionPower:3,thorns:0,deck:kind===1?['r01','r01','r02','r02','r03','r05','r11','r15']:kind===2?['m01','m01','m02','m03','m04','m05','m06','m11']:['v01','v01','v02','v03','v04','v06','v08','v11'],draw:[],discard:[],exhaust:[],hand:[],energy:3,strength:0,nextEnergy:0,played:false}}
function newRun(){let _seed=Math.floor(rng()*2**31);srand(_seed);G={mode:NET.active?'online':'duo',floor:0,gold:55,relic:'Нет',resonance:0,skillPoints:3,skills:[],skillHistory:[],respecs:0,pendingMod:null,mapNodes:genMapNodes(),heroes:[hero('Роуэн',1),hero('Мира',2)],completed:[],available:[0],current:null,seed:_seed};G.mapLinks=genMapLinks(G.mapNodes);G.roomMods=G.mapNodes.map(()=>rollRoomMod());G.gold+=metaStat(1,'startGold')+metaStat(2,'startGold');G.skillPoints+=Math.max(metaStat(1,'startPoint'),metaStat(2,'startPoint'));G.respecs+=metaStat(1,'freeRespec')+metaStat(2,'freeRespec');saveRun();showMap()}
function soloSelect(){openModal(`<div class="eyebrow">Одиночный режим</div><h2>Выберите узника</h2><p class="modal-sub">У каждого героя своя стартовая колода и стиль прохождения. В соло здоровье врагов сбалансировано под одного персонажа.</p><div class="choice-grid"><button class="choice" onclick="startSolo(1)"><div style="height:150px">${heroSVG(0)}</div><b>Роуэн · Железный клинок</b><span>72 ОЗ. Первая атака каждого раунда даёт 3 брони. Надёжный прямой урон.</span></button><button class="choice" onclick="startSolo(2)"><div style="height:150px">${heroSVG(1)}</div><b>Мира · Пепельная ведьма</b><span>62 ОЗ. Первый навык каждого раунда берёт карту. Лечение и кровотечение.</span></button><button class="choice" onclick="startSolo(3)"><div style="height:150px">${heroSVG(2)}</div><b>Вейра · Призывательница</b><span>58 ОЗ. Создаёт слуг, усиливает их и приносит в жертву ради мощных эффектов.</span></button></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Назад</button></div>`)}
function startSolo(kind){NET.active=false;NET.role=null;updateNetBadge();let h=hero(kind===1?'Роуэн':kind===2?'Мира':'Вейра',kind);let _seed=Math.floor(rng()*2**31);srand(_seed);G={mode:'solo',floor:0,gold:55,relic:'Нет',resonance:0,skillPoints:3,skills:[],skillHistory:[],respecs:0,pendingMod:null,mapNodes:genMapNodes(),heroes:[h],completed:[],available:[0],current:null,seed:_seed};G.mapLinks=genMapLinks(G.mapNodes);G.roomMods=G.mapNodes.map(()=>rollRoomMod());G.gold+=metaStat(kind,'startGold');G.skillPoints+=metaStat(kind,'startPoint');G.respecs+=metaStat(kind,'freeRespec');B=null;saveRun();showMap()}
function continueRun(){try{G=JSON.parse(localStorage.getItem('ashspire-save'));if(!G)throw 0;G.skillPoints??=3;G.skills??=[];G.skillHistory??=[];G.respecs??=0;G.pendingMod??=null;G.resonance??=0;if(!G.mapNodes){G.mapNodes=genMapNodes();G.completed=[];G.available=[0];G.current=null}srand(G.rngState??((G.seed>>>0)||1));G.mapLinks??=genMapLinks(G.mapNodes);G.roomMods??=G.mapNodes.map(()=>rollRoomMod());G.carryPoison??=0;G.heroes.forEach(h=>{h.position??=(h.kind===1?'front':'back');h.exhaust??=[];h.deck=(h.deck||[]).filter(id=>getCard(id));if(h.deck.length<5)h.deck=hero(h.name,h.kind).deck});NET.active=false;NET.role=null;B=null;updateNetBadge();showMap()}catch(e){soloSelect()}}
function saveRun(){if(G)G.rngState=RNG_STATE.s;if(G&&!NET.active)localStorage.setItem('ashspire-save',JSON.stringify(G));netSync()}
function showMap(){hideAll();$('#mapScreen').classList.remove('hidden');updateTop();renderPartyMini();renderMap();saveRun()}
function hideAll(){['#menu','#mapScreen','#battle'].forEach(x=>$(x).classList.add('hidden'));closeModal()}
function updateTop(){$('#floorUI').textContent=G?G.floor+'/7':'—';$('#goldUI').textContent=G?G.gold:'—';$('#relicUI').textContent=G?G.relic:'Нет'}
function renderPartyMini(){$('#partyMini').innerHTML=G.heroes.map((h,i)=>`<div class="hero-mini"><div class="mini-head"><div class="avatar">${i?'✦':'⚔'}</div><div><b>${esc(h.name)}</b><div class="small">Игрок ${i+1} · ${h.deck.length} карт</div></div></div><div class="hpbar"><i style="width:${100*h.hp/h.maxHp}%"></i></div><div class="small" style="text-align:right">${h.hp} / ${h.maxHp} ОЗ</div></div>`).join('')}
const MAP_ROWS=[92,78,63,47,31,13];
function pickMapType(r){if(r===0)return 'battle';if(r===1)return rng()<.6?'battle':'event';if(r===5)return 'boss';let w=[['battle',.36],['event',.18],['rest',.14],['elite',.2],['shop',.12]],x=rng(),acc=0;for(let [t,p] of w){acc+=p;if(x<acc)return t}return 'battle'}
function genMapNodes(){let nodes=[],rows=[];for(let r=0;r<6;r++){let count=r===0||r===5?1:r===1?2+(rng()<.5?1:0):2+(rng()<.45?1:0);let xs=count===1?[50]:count===2?[32,68]:[24,50,76];let row=[];xs.forEach(x=>{let t=pickMapType(r);let l={battle:'Бой',elite:'Элита',event:'Событие',rest:'Привал',boss:'Хранитель',shop:'Рынок'}[t];if(r===0){t='battle';l='Вход'}row.push({x,y:MAP_ROWS[r],t,l})});rows.push(row)}
if(!nodes.some(()=>false)){let all=rows.flat();if(!all.some(n=>n.t==='shop')){let cand=all.filter(n=>(n.y===47||n.y===31)&&n.t!=='boss');if(cand.length){let pick=cand[Math.floor(rng()*cand.length)];pick.t='shop';pick.l='Рынок'}}}
rows.flat().forEach(n=>nodes.push(n));return nodes}
function genMapLinks(nodes){let rows=[[],[],[],[],[],[]];nodes.forEach((n,i)=>rows[MAP_ROWS.indexOf(n.y)].push(i));let links=[];
for(let r=0;r<5;r++){let A=rows[r],Bn=rows[r+1];A.forEach((a,pos)=>{let j=Math.floor(pos*Bn.length/A.length);links.push([a,Bn[j]]);let j2=Math.min(Bn.length-1,j+1);if(j2!==j&&rng()<.5)links.push([a,Bn[j2]])});Bn.forEach(b=>{if(!links.some(l=>l[1]===b))links.push([A[Math.floor(rng()*A.length)],b])})}
return links.filter((l,idx)=>!links.slice(0,idx).some(m=>m[0]===l[0]&&m[1]===l[1]))}

function renderMap(){let mp=$('#mapPath');mp.innerHTML='';if(!G.mapNodes){G.mapNodes=genMapNodes();G.mapLinks=genMapLinks(G.mapNodes)}let nodes=G.mapNodes,links=G.mapLinks;let reveal=G&&G.heroes&&G.heroes.some(h=>metaStat(h.kind,'revealRooms'));links.forEach(([a,b])=>{let A=nodes[a],C=nodes[b],dx=(C.x-A.x)/100*mp.clientWidth,dy=(C.y-A.y)/100*620,len=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)*180/Math.PI;mp.insertAdjacentHTML('beforeend',`<i class="pathline" style="left:${A.x}%;top:${A.y}%;width:${len}px;transform:rotate(${ang}deg)"></i>`)});nodes.forEach((n,i)=>{let state=G.completed.includes(i)?'done':G.available.includes(i)?'available':'locked';let ic={battle:'⚔',elite:'☠',event:'?',rest:'♨',boss:'◆',shop:'🛒'}[n.t];mp.insertAdjacentHTML('beforeend',`<button class="node ${state} ${n.t==='boss'?'boss':''}" data-label="${n.l}" style="left:${n.x}%;top:${n.y}%" onclick="chooseNode(${i})" ${state!=='available'?'disabled':''}>${reveal&&G.roomMods&&G.roomMods[i]&&(n.t==='battle'||n.t==='elite'||n.t==='boss')?`<em class="node-mod ${G.roomMods[i].kind}" title="${G.roomMods[i].name}: ${G.roomMods[i].desc}">${G.roomMods[i].kind==='blessing'?'✦':'☾'}</em>`:''}<span>${ic}</span></button>`)});}
function chooseNode(i){if(NET.active&&NET.role!=='host'){toast('Маршрут выбирает Игрок 1');return}if(!G.available.includes(i))return;G.current=i;G.floor++;let n=G.mapNodes[i];G.pendingMod=(n.t==='battle'||n.t==='elite'||n.t==='boss')?(G.roomMods&&G.roomMods[i]!==undefined?G.roomMods[i]:rollRoomMod()):null;if(n.t==='battle'||n.t==='elite'||n.t==='boss')startBattle(n.t);else if(n.t==='rest')restEvent();else if(n.t==='shop')shopEvent();else storyEvent();}
function completeNode(){let i=G.current??0;if(!G.completed.includes(i)){G.completed.push(i);G.skillPoints=(G.skillPoints||0)+(G.mapNodes[i].t==='elite'?2:1)}G.available=G.mapLinks.filter(x=>x[0]===i).map(x=>x[1]);if(i===G.mapNodes.length-1){victory();return}showMap()}
function startBattle(type){playSfx(type==='boss'?'boss':'battle');hideAll();$('#battle').classList.remove('hidden');let scale=1+G.floor*.12,hp=Math.round((type==='boss'?130:type==='elite'?82:54)*scale*(G.mode==='solo'?.72:1)*(G.pendingMod?.effect==='hunger'?1.3:1));G.resonance=0;B={type,enemy:{phase:1,archetype:G.floor%3,name:type==='boss'?'Сердце Печи':type==='elite'?'Позолоченный Жнец':['Пепельный пёс','Полый страж','Костяной звонарь'][G.floor%3],hp,maxHp:hp,block:0,bleed:0,poison:0,vuln:0,weak:0,doom:0},roomMod:G.pendingMod,round:1,active:0,turnCards:0,log:[],intent:null};G.heroes.forEach(h=>{h.block=0;h.position=h.kind===1?'front':'back';h.draw=shuffle([...h.deck]);h.discard=[];h.exhaust=[];h.hand=[];h.strength=0;h.played=false;h.nextEnergy=0;h.minions=0;h.minionPower=3;h.thorns=skillStat(h,'thorns');h.lastDropUsed=false;h.moonUsed=false;h.recycleUsed=false;h.avatarSaved=false;h.lostMinions=0;h.recentLoss=0;h.freePlays=0});if(G.carryPoison>0){B.enemy.poison=G.carryPoison;G.carryPoison=0;log(`Яд переносится в бой: ${B.enemy.poison}.`)}rollIntent();startRound();}
function shuffle(a){for(let i=a.length-1;i;i--){let j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function draw(h,n){n=Math.max(0,n|0);while(n--){if(!h.draw.length&&h.discard.length){h.draw=shuffle(h.discard.splice(0));if(B){log(`Сброс ${h.name} перемешан и стал новой колодой добора.`);playSfx('shuffle');animateShuffle()}}if(h.draw.length&&h.hand.length<8){h.hand.push(h.draw.pop());if(h.hand.length>5&&hasTrait(h,'forbidden'))h.freePlays=(h.freePlays||0)+1}}}
function startRound(){B.dealAnim=true;B.vulnAtStart=B.enemy.vuln;B.weakAtStart=B.enemy.weak;G.heroes.forEach(h=>{let retained=hasTrait(h,'ironVow')?h.block:Math.floor(h.block*skillStat(h,'retainBlock')/100);h.block=retained;h.energy=3+h.nextEnergy-(hasTrait(h,'ironVow')?1:0);h.nextEnergy=0;h.played=false;h.passiveUsed=false;h.attacksPlayed=0;h.heavyPlayed=false;h.sacrificeUsed=false;h.sacrificesThisBattle??=0;h.discountUsed=false;h.refilledThisRound=false;if(hasTrait(h,'autoSummon'))summonMinion(h,1);if(hasTrait(h,'avatarWard')&&h.minions)h.block+=skillStat(h,'avatarWard');let bonusDraw=B.round===1?skillStat(h,'draw'):0;draw(h,5-h.hand.length+bonusDraw);h.freePlays=0});if(B.round>1&&B.round%3===0)G.heroes.forEach(h=>{if(hasTrait(h,'fullMoon')&&h.recentLoss>0&&h.hp>0){let hv=Math.min(h.maxHp-h.hp,Math.floor(h.recentLoss*.5));if(hv>0){h.hp+=hv;log(`Полная луна восстанавливает ${h.name} на ${hv}.`)}}h.recentLoss=0});G.heroes.forEach(h=>{if(h.lostMinions>0&&hasTrait(h,'endlessArmy')){summonMinion(h,h.lostMinions);log(`Армия без конца: к ${h.name} возвращаются слуги.`)}h.lostMinions=0});if(B.round===1){G.heroes.forEach(h=>{h.energy+=skillStat(h,'energy');h.block+=skillStat(h,'block');if(B.roomMod?.effect==='energy')h.energy+=1+(hasTrait(h,'blessingPower')?1:0);if(B.roomMod?.effect==='strength')h.strength+=3+(hasTrait(h,'blessingPower')?2:0);if(B.roomMod?.effect==='ward')h.block+=10;if(B.roomMod?.effect==='frail')h.energy=Math.max(1,h.energy-1)});if(B.roomMod?.effect==='fortified')B.enemy.block+=12}B.active=0;B.turnCards=0;log(`— Раунд ${B.round}. Ход ${G.heroes[0].name}.`);renderBattle()}
function rollIntent(){let r=rng(),base=5+G.floor,e=B.enemy;if(B.type==='boss'){let p=e.phase||1;B.intent=p===1?(r<.55?{kind:'attack',dmg:10+G.floor,hits:1,target:'front'}:{kind:'defend',block:16}):p===2?(r<.6?{kind:'attack',dmg:6+G.floor,hits:2,target:'back'}:{kind:'curse',dmg:5,target:'all'}):(r<.7?{kind:'attack',dmg:7+G.floor,hits:3,target:'front'}:{kind:'burn',dmg:10,target:'all'});return}if(B.type==='elite'){B.intent=r<.55?{kind:'attack',dmg:base+5,hits:r<.25?2:1,target:r<.45?'back':'front'}:r<.78?{kind:'defend',block:10+G.floor}:{kind:'curse',dmg:4,target:'all'};return}if(e.archetype===0)B.intent=r<.75?{kind:'attack',dmg:base,hits:r<.3?2:1,target:'front'}:{kind:'charge',dmg:base+5,target:'front'};else if(e.archetype===1)B.intent=r<.5?{kind:'attack',dmg:base+2,hits:1,target:'front'}:{kind:'defend',block:8+G.floor};else B.intent=r<.45?{kind:'attack',dmg:base,hits:1,target:'back'}:r<.75?{kind:'curse',dmg:3,target:'all'}:{kind:'defend',block:6+G.floor}}
function renderBattle(){updateTop();NET.phase='battle';applyArenaArt();$('#roundUI').textContent='Раунд '+B.round;$('#battleName').innerHTML=B.type==='boss'?`ХРАНИТЕЛЬ ВЕРШИНЫ <span class="phase-pip">ФАЗА ${B.enemy.phase||1}/3</span>`:B.type==='elite'?'ЭЛИТНЫЙ ПРОТИВНИК':'СТОЛКНОВЕНИЕ';$('#roomModUI').innerHTML=B.roomMod?`<span class="room-mod ${B.roomMod.kind}" title="${esc(B.roomMod.desc)}">${B.roomMod.kind==='blessing'?'✦':'☾'} ${esc(B.roomMod.name)}</span>`:'';$('#battleParty').innerHTML=G.heroes.map((h,i)=>unitHTML(h,i)).join('');let e=B.enemy;$('#enemyUI').innerHTML=`<div class="sprite enemy ${B.type}">${enemySVG(B.type)}</div><div class="unit-name">${esc(e.name)}</div><div id="previewUI" class="preview-damage"></div><div class="health"><div class="txt">${e.hp} / ${e.maxHp}${e.block?` · <span class="shield">◈ ${e.block}</span>`:''}</div><div class="hpbar"><i style="width:${100*e.hp/e.maxHp}%"></i></div></div><div class="status-row">${e.bleed?`<span class="status">🩸 ${e.bleed}</span>`:''}${e.poison?`<span class="status">☠ ${e.poison}</span>`:''}${e.vuln?`<span class="status">◈ Уязвимость</span>`:''}${e.weak?`<span class="status">▽ Слабость</span>`:''}${e.doom?`<span class="status">☾ ${e.doom}</span>`:''}</div>`;let it=B.intent,target=G.heroes.length===1&&it.target!=='all'?' · ваш герой':it.target==='front'?' · приоритет: передний ряд':it.target==='back'?' · приоритет: задний ряд':it.target==='all'?' · весь отряд':'';$('#intentUI').textContent=it.kind==='attack'||it.kind==='charge'?`⚔ ${it.kind==='charge'?'Готовит рывок':'Намерение'}: ${it.dmg}${it.hits>1?' × '+it.hits:''} урона${target}`:it.kind==='defend'?`🛡 Намерение: ${it.block} брони`:`☾ ${it.kind==='burn'?'Сжечь карты':'Наложить проклятие'}${target}`;$('#resonanceUI').textContent=`Резонанс · ${G.resonance||0}/10`;$('#resonanceUI').classList.toggle('ready',(G.resonance||0)>=3);let h=G.heroes[B.active];$('#energyUI').textContent=h.energy;$('#activeUI').textContent=G.mode==='solo'?`Соло · ${h.name}`:`Игрок ${B.active+1} · ${h.name}`;let hSig=h.hand.join(',')+'#'+h.energy+'#'+B.active+'#'+(h.freePlays||0);let handUI=$('#handUI');if(handUI.dataset.sig!==hSig){handUI.innerHTML=h.hand.map((id,i)=>cardHTML(id,i,h.energy<effectiveCost(getCard(id),h))).join('');handUI.dataset.sig=hSig}$('#drawCount').textContent=h.draw.length;$('#discardCount').textContent=h.discard.length;$('#exhaustCount').textContent=(h.exhaust||[]).length;$('#pileUI').textContent='Нажмите на стопку, чтобы посмотреть карты';renderCombatLog();B.dealAnim=false;if(NET.active){let locked=!canAct();$('#handUI').classList.toggle('remote-lock',locked);$('.end-turn').disabled=locked}netSync()}
function unitHTML(h,i){return`<div class="fighter ${B&&B.active===i?'active':'inactive'}"><div class="sprite hero${i+1}">${heroSVG(h.kind-1)}</div><div class="unit-name">${esc(h.name)}</div><span class="position-badge">${h.position==='front'?'передний ряд':'задний ряд'}</span><div class="health"><div class="txt">${h.hp}/${h.maxHp}${h.block?` · <span class="shield">◈ ${h.block}</span>`:''}</div><div class="hpbar"><i style="width:${100*h.hp/h.maxHp}%"></i></div></div><div class="minion-row">${h.minions?`☠ Слуги: ${h.minions} · сила ${h.minionPower}`:''}</div><div class="status-row">${h.strength?`<span class="status">🔥 +${h.strength}</span>`:''}</div></div>`}
function cardHTML(id,i,disabled=false){let c=getCard(id)||{name:'???',cost:0,type:'skill',icon:'🃏',text:'Неизвестная карта',tags:[]},owner=B&&i<100?G.heroes[B.active]:null,cost=owner?effectiveCost(c,owner):c.cost,text=G&&G.mode==='solo'?c.text.replace('Оба героя получают','Получите'):c.text,art=(typeof CARD_ART!=='undefined'&&CARD_ART[id])?`<img class="ai-card-art" src="${CARD_ART[id]}" alt="${c.name}">`:c.artSeed?generatedArt(c.artSeed,c.type):c.icon;return`<button type="button" class="card ${c.type} ${c.rarity||''} ${disabled?'disabled':''}" aria-label="${esc(c.name)} — ${esc(c.text)}"${disabled?' aria-disabled="true"':''} style="${B&&B.dealAnim?`animation-delay:${Math.min(i,7)*.045}s`:'animation:none'}" onmouseenter="previewCard('${id}',this)" onmouseleave="clearCardPreview()" onclick="playCard(${i},event)"><i class="cost">${cost}</i><div class="card-name">${c.name}</div><div class="card-art">${art}</div><div class="rarity">${rarityName(c.rarity)}</div><div class="card-text">${richCardText(text)}</div><div class="card-type">${(c.tags&&c.tags.length)?c.tags.slice(0,2).join(' · '):(c.type==='attack'?'атака':c.type==='skill'?'навык':'приём')}</div></button>`}
// ── Таблица эффектов карт (effects-as-data): упорядочена как исходный playCard, ──
// ── порядок выполнения важен (block → blockStrike, dmg → bleed и т.д.) ──
const CARD_EFFECTS=[
{k:'selfDmg',f(h,c,ctx){if(c.selfDmg){damageHero(h,c.selfDmg);if(hasTrait(h,'selfPower'))h.strength+=skillStat(h,'selfPower')}}},
{k:'dmg',f(h,c,ctx){if(c.dmg){let d=c.dmg+ctx.synergy+h.strength+(h.nextAttack||0)+(c.comboScale||0)*h.attacksPlayed+skillStat(h,'heavyDamage')*(c.cost>=2)+skillStat(h,'firstAttack')*(h.attacksPlayed===0)+skillStat(h,'comboDamage')*h.attacksPlayed+(h.hp<h.maxHp/2?skillStat(h,'lowHpDamage'):0)+(h.hand.length>=5?skillStat(h,'handPower'):0),hits=c.hits||1;if(c.bleedExecute&&B.enemy.bleed>=8)d*=c.bleedExecute;if(h.nextAttack)h.nextAttack=0;if(h.doubleHeavy&&c.cost>=2){hits*=2;h.doubleHeavy=false}if(hasTrait(h,'doubleHeavy')&&c.cost>=2&&!h.heavyPlayed){hits*=2;h.heavyPlayed=true;B.enemy.weak+=1}h.strength=0;h.attacksPlayed++;for(let z=0;z<hits;z++)damageEnemy(d);if(skillStat(h,'thirdHit')&&h.attacksPlayed%3===0)damageEnemy(skillStat(h,'thirdHit'));log(`${h.name} играет «${c.name}»: ${d}${hits>1?' × '+hits:''} урона.`)}}},
{k:'block',f(h,c,ctx){if(c.block){let bv=(c.block+(h.blessPower||0))*(hasTrait(h,'livingFortress')?2:1);if(h.noArmor)bv=0;h.block+=bv;log(`${h.name} получает ${bv} брони.`)}}},
{k:'allBlock',f(h,c,ctx){if(c.allBlock)G.heroes.forEach(x=>x.block+=c.allBlock);}},
{k:'heal',f(h,c,ctx){if(c.heal){let t=[...G.heroes].sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0],hv=c.heal+skillStat(h,'healPower')+(h.blessPower||0),before=t.hp;t.hp=Math.min(t.maxHp,t.hp+hv);if(hasTrait(h,'overhealBlock'))t.block+=Math.max(0,before+hv-t.maxHp);log(`${t.name} восстанавливает ${hv} ОЗ.`);let ah=skillStat(h,'allyHeal');if(ah&&t===h){let al=G.heroes.find(x=>x!==h&&x.hp>0);if(al){al.hp=Math.min(al.maxHp,al.hp+ah);log(`${al.name} получает ${ah} ОЗ от общего света.`)}}}}},
{k:'draw',f(h,c,ctx){if(c.draw)draw(h,c.draw);}},
{k:'strength',f(h,c,ctx){if(c.strength){h.strength+=c.strength;if(skillStat(h,'avatarStrength'))h.minionPower+=Math.ceil(c.strength*.5)}}},
{k:'bleed',f(h,c,ctx){if(c.bleed)B.enemy.bleed+=c.bleed+skillStat(h,'bleed');}},
{k:'nextEnergy',f(h,c,ctx){if(c.nextEnergy)G.heroes.forEach(x=>x.nextEnergy+=c.nextEnergy);}},
{k:'energyGain',f(h,c,ctx){if(c.energyGain)h.energy+=c.energyGain;}},
{k:'poison',f(h,c,ctx){if(c.poison){let pv=c.poison+skillStat(h,'poison');if(hasTrait(h,'plagueWord'))pv*=2;B.enemy.poison+=pv;if(skillStat(h,'poisonBurst')&&B.enemy.poison>=20){let pd=Math.floor(B.enemy.poison/2);B.enemy.poison-=pd;B.enemy.hp-=pd;log(`Яд вспыхивает: мгновенно ${pd} урона.`)}}}},
{k:'vuln',f(h,c,ctx){if(c.vuln)B.enemy.vuln+=c.vuln;}},
{k:'weak',f(h,c,ctx){if(c.weak)B.enemy.weak+=c.weak;}},
{k:'doom',f(h,c,ctx){if(c.doom)B.enemy.doom+=c.doom+skillStat(h,'doom');}},
{k:'thorns',f(h,c,ctx){if(c.thorns)h.thorns+=c.thorns;}},
{k:'summon',f(h,c,ctx){if(c.summon){summonMinion(h,c.summon);h.minionPower=Math.max(h.minionPower,c.minionPower||3);h.block+=skillStat(h,'summonBlock')*c.summon}}},
{k:'minionBuff',f(h,c,ctx){if(c.minionBuff)h.minionPower+=c.minionBuff;}},
{k:'sacrificeMinion',f(h,c,ctx){if(c.sacrificeMinion&&h.minions>0){let mult=hasTrait(h,'tripleDeath')?3:hasTrait(h,'doubleSacrifice')&&!h.sacrificeUsed?2:1;h.sacrificeUsed=true;loseMinion(h,1);h.sacrificesThisBattle++;if(hasTrait(h,'sacrificeCircle')&&h.sacrificesThisBattle%3===0)h.freeNext=true;damageEnemy((8+h.minionPower+skillStat(h,'sacrificeDamage'))*mult);h.block+=skillStat(h,'sacrificeBlock')*mult;h.hp=Math.min(h.maxHp,h.hp+skillStat(h,'sacrificeHeal')*mult);if(skillStat(h,'sacrificeEnergy'))h.energy+=skillStat(h,'sacrificeEnergy');if(hasTrait(h,'recycleSummon')){let idxs=h.discard.map((x,j)=>(getCard(x).tags||[]).includes('призыв')?j:-1).filter(j=>j>=0);if(idxs.length&&h.hand.length<8){let pick=idxs[Math.floor(rng()*idxs.length)];h.hand.push(h.discard.splice(pick,1)[0]);log('Обратный зов возвращает карту призыва в руку.')}}}}},
{k:'cleanse',f(h,c,ctx){if(c.cleanse){h.hp=Math.min(h.maxHp,h.hp+2);h.block+=2+skillStat(h,'cleanseBlock')}}},
{k:'blockStrike',f(h,c,ctx){if(c.blockStrike)damageEnemy(Math.floor(h.block*c.blockStrike));}},
{k:'protect',f(h,c,ctx){if(c.protect)h.protect=true;}},
{k:'move',f(h,c,ctx){if(c.move)h.position=c.move;}},
{k:'taunt',f(h,c,ctx){if(c.taunt)h.taunt=true;}},
{k:'delay',f(h,c,ctx){if(c.delay)B.delayed=true;}},
{k:'nextAttack',f(h,c,ctx){if(c.nextAttack)h.nextAttack=(h.nextAttack||0)+c.nextAttack;}},
{k:'lowHpBlock',f(h,c,ctx){if(c.lowHpBlock&&h.hp<h.maxHp/2)h.block+=c.lowHpBlock;}},
{k:'gainRes',f(h,c,ctx){if(c.gainRes)gainResonance(c.gainRes);}},
{k:'poisonBurst',f(h,c,ctx){if(c.poisonBurst&&B.enemy.poison){let pd=Math.floor(B.enemy.poison*c.poisonBurst);B.enemy.hp-=pd;log(`Яд вспыхивает и наносит ${pd} урона.`)}}},
{k:'reflectSpell',f(h,c,ctx){if(c.reflectSpell)h.reflectSpell=true;}},
{k:'discard',f(h,c,ctx){if(c.discard&&h.hand.length){let di=h.hand.map((x,j)=>[getCard(x).cost,j]).sort((a,b)=>b[0]-a[0])[0][1];h.discard.push(h.hand.splice(di,1)[0])}}},
{k:'stealIntent',f(h,c,ctx){if(c.stealIntent){B.delayed=true;h.energy++}}},
{k:'bless',f(h,c,ctx){if(c.bless)h.blessPower=(h.blessPower||0)+2;}},
{k:'recycle',f(h,c,ctx){if(c.recycle){let ri=h.discard.length-2;if(ri>=0&&h.hand.length<8)h.hand.push(h.discard.splice(ri,1)[0])}}},
{k:'recycleSummon',f(h,c,ctx){if(c.recycleSummon){let ri=h.discard.findLastIndex(x=>(getCard(x).tags||[]).includes('призыв'));if(ri>=0&&h.hand.length<8)h.hand.push(h.discard.splice(ri,1)[0])}}},
{k:'command',f(h,c,ctx){if(c.command&&h.minions)damageEnemy(h.minions*(h.minionPower+skillStat(h,'minion')));}},
{k:'protectByMinion',f(h,c,ctx){if(c.protectByMinion&&h.minions)h.minionGuard=true;}},
{k:'sacrificeAll',f(h,c,ctx){if(c.sacrificeAll&&h.minions){let n=h.minions;loseMinion(h,n);damageEnemy(n*7)}}},
{k:'avatar',f(h,c,ctx){if(c.avatar&&h.minions>1){h.minionPower+=h.minions*2;h.minions=1}}},
{k:'noArmor',f(h,c,ctx){if(c.noArmor)h.noArmor=true;}},
{k:'emptyRefill',f(h,c,ctx){if(c.emptyRefill)h.emptyRefill=true;}},
{k:'nextDoubleHeavy',f(h,c,ctx){if(c.nextDoubleHeavy)h.doubleHeavy=true;}},
{k:'exhaust',f(h,c,ctx){if(c.exhaust){if(hasTrait(h,'recycle')&&!h.recycleUsed){h.recycleUsed=true;log('Память пепла: карта вернётся в сброс вместо Пепла.')}else{let xi=h.discard.lastIndexOf(ctx.id);if(xi>=0)h.discard.splice(xi,1);(h.exhaust??=[]).push(ctx.id)}}}},
];

function playCard(i,ev){if(i>=100)return;if(!canAct()){toast('Сейчас ход напарника');return;}let h=G.heroes[B.active],id=h.hand[i],c=getCard(id),paid=effectiveCost(c,h);if(!c||h.energy<paid){toast('Не хватает энергии');playSfx('error');return}playSfx(c.type==='attack'?'attack':c.heal?'heal':'card');h.energy-=paid;if(paid===0&&hasTrait(h,'forbidden')&&h.freePlays>0&&c.cost>0)h.freePlays--;if(hasTrait(h,'firstDiscount')&&c.cost>=2&&!h.discountUsed)h.discountUsed=true;if(h.freeNext)h.freeNext=false;h.hand.splice(i,1);h.discard.push(id);if(G.mode==='solo'&&!h.passiveUsed&&((h.kind===1&&c.type==='attack')||(h.kind===2&&c.type==='skill'))){h.passiveUsed=true;if(h.kind===1){h.block+=3;log('Стойка Роуэна даёт 3 брони.')}else{draw(h,1);log('Чутьё Миры позволяет взять карту.')}}let ally=G.heroes.length>1?G.heroes[1-B.active]:null;let synergy=ally&&ally.played&&c.combo?c.combo:0;let ctx={id,synergy};for(let e of CARD_EFFECTS)e.f(h,c,ctx);updateResonance(h,c);h.played=true;B.turnCards++;if(h.emptyRefill&&h.hand.length===0&&!h.refilledThisRound){h.refilledThisRound=true;draw(h,4)}else if(h.hand.length===0&&!h.refilledThisRound&&skillStat(h,'emptyRefill')){h.refilledThisRound=true;draw(h,3);log('Разорванная причинность восполняет пустую руку.')}if(B.enemy.hp<=0){battleWon();return}if(h.hp<=0){if(checkTeamWipe())return;if(h.hp<=0){log(`${h.name} падает…`);toast(`${h.name} выведен из строя`);endPlayerTurn();return}}renderBattle();netSync()}
function gainResonance(n){G.resonance=Math.min(10,(G.resonance||0)+n)}
function updateResonance(h,c){let tags=c.tags||[],shared=B.lastTags&&tags.some(t=>B.lastTags.includes(t));if(shared&&(G.mode==='solo'||B.lastPlayer!==B.active))gainResonance(1);if(tags.includes('командная'))gainResonance(1);B.lastTags=tags;B.lastPlayer=B.active}
function showTeamMoves(){if(!B)return;let r=G.resonance||0;openModal(`<div class="eyebrow">Общий ресурс</div><h2>Резонанс · ${r}/10</h2><p class="modal-sub">Резонанс возникает из последовательных карт с общими тегами. Командные приёмы не тратят энергию.</p><div class="choice-grid"><button class="team-move" ${r<3?'disabled':''} onclick="teamMove('guard',3)"><b>Общий заслон · 3</b><span>Все герои получают 12 брони.</span></button><button class="team-move" ${r<5?'disabled':''} onclick="teamMove('strike',5)"><b>Согласованный удар · 5</b><span>25 урона и Уязвимость.</span></button><button class="team-move" ${r<6?'disabled':''} onclick="teamMove('rescue',6)"><b>Не оставлять своих · 6</b><span>Поднять павшего союзника или исцелить отряд.</span></button><button class="team-move" ${r<2?'disabled':''} onclick="teamMove('shift',2)"><b>Смена строя · 2</b><span>Поменять позиции и взять по карте.</span></button></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Отмена</button></div>`)}
function teamMove(type,cost){if((G.resonance||0)<cost)return;G.resonance-=cost;if(type==='guard')G.heroes.forEach(h=>h.block+=12);if(type==='strike'){damageEnemy(25);B.enemy.vuln++}if(type==='rescue')G.heroes.forEach(h=>{h.hp=h.hp<=0?Math.ceil(h.maxHp*.25):Math.min(h.maxHp,h.hp+6)});if(type==='shift')G.heroes.forEach(h=>{h.position=h.position==='front'?'back':'front';draw(h,1)});closeModal();playSfx(type==='strike'?'attack':'heal');if(B.enemy.hp<=0)battleWon();else renderBattle();netSync()}
function effectiveCost(c,h){let cost=c.cost;if(hasTrait(h,'livingFortress')&&c.type==='attack')cost++;if(hasTrait(h,'firstDiscount')&&c.cost>=2&&!h.discountUsed)cost--;if(hasTrait(h,'weaponMaster')&&c.type==='attack'&&h.attacksPlayed===2)cost=0;if(h.freeNext)cost=0;if(hasTrait(h,'forbidden')&&h.freePlays>0)cost=0;return Math.max(0,cost)}
function summonMinion(h,n){let max=(hasTrait(h,'legion')?10:5)+skillStat(h,'maxMinion');if(hasTrait(h,'singleAvatar')){if(h.minions){h.minionPower+=n*(2+skillStat(h,'absorbSummon'));return}max=1}h.minions=Math.min(max,h.minions+n)}
function damageEnemy(d){combatAnim('enemy');let e=B.enemy,h=G.heroes[B.active]||G.heroes[0];d+=skillStat(h,'damage');if(skillStat(h,'armorDamage')&&h.block>=20)d=Math.ceil(d*1.2);if(hasTrait(h,'bloodOath')&&h.hp<h.maxHp/2)d+=skillStat(h,'lowHpDamage');if(e.vuln)d=Math.ceil(d*1.35);let blocked=Math.min(e.block,d);e.block-=blocked;e.hp-=d-blocked;checkBossPhase();floatText(`-${d-blocked}`,70,30,'#ef7463')}
function loseMinion(h,n=1){let had=h.minions;h.minions-=n;if(h.minions<=0&&hasTrait(h,'immortalAvatar')&&!h.avatarSaved){h.avatarSaved=true;h.minions=1;h.minionPower=Math.max(1,Math.floor(h.minionPower*.5));log('Бессмертный спутник выживает с половиной силы.')}h.lostMinions=(h.lostMinions||0)+Math.max(0,had-h.minions)}function checkBossPhase(){if(B.type!=='boss')return;let e=B.enemy,next=e.hp<=e.maxHp*.33?3:e.hp<=e.maxHp*.66?2:1;if(next>e.phase){e.phase=next;e.block+=15*next;B.lastTags=null;log(`Сердце Печи переходит в фазу ${next}!`);playSfx('boss')}}
function checkTeamWipe(){if(!G.heroes.every(h=>h.hp<=0))return false;let savior=G.heroes.find(h=>metaStat(h.kind,'secondChance'))&&!G.secondChanceUsed?G.heroes.find(h=>metaStat(h.kind,'secondChance')):null;if(savior){G.secondChanceUsed=true;savior.hp=1;log('Наследие не позволяет забегу окончиться.');return false}defeat();return true}function damageHero(h,d){combatAnim('hero');playSfx('hurt');let blocked=Math.min(h.block,d);h.block-=blocked;h.hp-=d-blocked;h.recentLoss=(h.recentLoss||0)+d-blocked;if(h.hp<=0&&hasTrait(h,'lastDrop')&&!h.lastDropUsed){h.lastDropUsed=true;h.hp=1;log(`${h.name} держится на последней капле.`)}if(h.hp<=0&&hasTrait(h,'moonRebirth')&&!h.moonUsed){h.moonUsed=true;h.hp=Math.ceil(h.maxHp*.2);log(`Неугасимая луна возвращает ${h.name}.`)}if(blocked===d&&skillStat(h,'counter'))B.enemy.hp-=skillStat(h,'counter');if(h.thorns&&d-blocked>0)B.enemy.hp-=h.thorns;log(`${h.name} получает ${d-blocked} урона.`)}
function endPlayerTurn(){if(!canAct()){toast('Сейчас ход напарника');return}let h=G.heroes[B.active];h.discard.push(...h.hand.splice(0));if(G.heroes.length>1&&B.active===0){B.active=1;log(`Ход ${G.heroes[1].name}.`);renderBattle();return}enemyTurn()}
function resolveEnemyTarget(intent,alive){if(!alive.length)return null;let taunter=alive.find(h=>h.taunt);if(taunter)return taunter;if(G.mode==='solo'||alive.length===1)return alive[0];let wanted=intent.target||'front',preferred=alive.filter(h=>h.position===wanted);if(preferred.length)return preferred[Math.floor(rng()*preferred.length)];let fallback=wanted==='front'?'back':'front',other=alive.filter(h=>h.position===fallback);if(other.length){log(`${B.enemy.name} прорывается в ${fallback==='back'?'задний':'передний'} ряд.`);return other[Math.floor(rng()*other.length)]}return alive[Math.floor(rng()*alive.length)]}
function showPile(type){if(!B)return;let h=G.heroes[B.active],cards=[...(h[type]||[])],titles={draw:'Колода добора',discard:'Сброс',exhaust:'Истощённые карты'},note=type==='draw'?'Порядок карт скрыт. При опустошении сброс автоматически перемешивается.':type==='discard'?'Эти карты вернутся после перемешивания.':'Эти карты не вернутся в текущем бою.',counts=cards.reduce((a,id)=>(a[id]=(a[id]||0)+1,a),{});openModal(`<div class="eyebrow">${esc(h.name)}</div><h2>${titles[type]} · ${cards.length}</h2><p class="modal-sub">${note}</p><div class="pile-list">${Object.entries(counts).map(([id,n])=>{let c=getCard(id)||{icon:'🃏',name:'???',rarity:'',tags:[],type:'skill'};return `<div class="pile-entry"><i>${c.artSeed?generatedArt(c.artSeed,c.type):c.icon}</i><div><b>${c.name}${n>1?' ×'+n:''}</b><small>${c.rarity?rarityName(c.rarity)+' · ':''}${(c.tags||[]).join(' · ')||c.type}</small></div></div>`}).join('')||'<p class="small">Стопка пуста.</p>'}</div><div class="modal-actions"><button class="btn" onclick="closeModal()">Вернуться в бой</button></div>`)}
function animateShuffle(){let el=$('.pile-buttons');if(!el)return;el.classList.remove('shuffle-flash');void el.offsetWidth;el.classList.add('shuffle-flash');setTimeout(()=>el.classList.remove('shuffle-flash'),600)}
function enemyTurn(){let e=B.enemy,it=B.intent;if(B.delayed){B.delayed=false;log('Действие врага сорвано.');B.round++;rollIntent();startRound();return}if(it.kind==='attack'||it.kind==='charge'){for(let k=0;k<(it.hits||1);k++){let alive=G.heroes.filter(h=>h.hp>0),t=resolveEnemyTarget(it,alive),protector=alive.find(h=>h.protect&&h!==t);if(protector)t=protector;if(t){if(t.minionGuard&&t.minions){loseMinion(t,1);t.minionGuard=false;log('Слуга принимает удар вместо героя.')}else damageHero(t,Math.max(1,it.dmg-(e.weak?3:0)-skillStat(t,'weakPower')-(t.minions>0?2*skillStat(t,'avatarGuard'):0)))}}}else if(it.kind==='defend'){e.block+=it.block;log(`${e.name} получает ${it.block} брони.`)}else if(it.kind==='curse'||it.kind==='burn'){G.heroes.filter(h=>h.hp>0).forEach(h=>damageHero(h,it.dmg));if(it.kind==='burn')G.heroes.forEach(h=>{if(h.draw.length)h.draw.pop()})}G.heroes.forEach(h=>{h.taunt=false;h.protect=false});if(e.bleed){e.hp-=e.bleed;log(`Кровотечение наносит врагу ${e.bleed} урона.`)}if(e.poison){e.hp-=e.poison;log(`Яд наносит ${e.poison} урона.`);G.heroes.forEach(x=>{let pblk=skillStat(x,'poisonBlock');if(pblk&&x.hp>0)x.block+=pblk});if(G.heroes.some(x=>hasTrait(x,'poisonArmor')))e.block=Math.max(0,e.block-e.poison);if(!G.heroes.some(h=>hasTrait(h,'poisonPersist')||hasTrait(h,'eternalPoison')))e.poison=Math.max(0,e.poison-1)}if(e.poison&&G.heroes.some(h=>hasTrait(h,'eternalPoison'))){e.hp-=e.poison;log(`Вечная болезнь наносит ещё ${e.poison} урона.`)}if(e.doom){e.hp-=e.doom;log(`Рок наносит ${e.doom} урона.`)}G.heroes.forEach(h=>{if(h.minions>0){let md=h.minions*(h.minionPower+skillStat(h,'minion'))*(hasTrait(h,'legion')?.7:1);if(hasTrait(h,'perfectAvatar')&&h.minions===1)md*=2;e.hp-=Math.floor(md);if(hasTrait(h,'minionLeech'))h.hp=Math.min(h.maxHp,h.hp+Math.max(1,Math.floor(md*.08)));if(hasTrait(h,'avatarPoison'))B.enemy.poison+=skillStat(h,'avatarPoison');log(`Слуги ${h.name} наносят ${Math.floor(md)} урона.`)}});if(e.hp<=0){battleWon();return}if(checkTeamWipe())return;G.heroes.forEach(h=>{if(h.hp<0)h.hp=0});e.vuln=Math.max(0,e.vuln-Math.min(e.vuln,B.vulnAtStart||0));e.weak=Math.max(0,e.weak-Math.min(e.weak,B.weakAtStart||0));B.round++;rollIntent();startRound()}
function battleWon(){playSfx('win');let gain=B.type==='boss'?100:B.type==='elite'?45:24;G.gold+=gain;G.heroes.forEach(h=>{let kh=skillStat(h,'killHeal');if(kh&&h.hp>0){h.hp=Math.min(h.maxHp,h.hp+kh);log(`Жажда боя лечит ${h.name} на ${kh}.`)}});if(B.enemy.poison>0&&G.heroes.some(h=>hasTrait(h,'spreadPoison')))G.carryPoison=Math.floor(B.enemy.poison*.5);setTimeout(()=>rewardModal(gain),250)}
function rewardModal(gain){let classPool=G.heroes.flatMap(h=>CLASS_CARDS[h.kind]||[]),pool=[...REWARDS,...classPool];if(G.heroes.length===1)pool=pool.filter(x=>x!=='twin'&&x!=='cover');let extra=Math.max(...G.heroes.map(h=>metaStat(h.kind,'extraChoice'))),opts=rollCardRewards(pool,3+extra,Math.max(0,...G.heroes.map(h=>metaStat(h.kind,'rareBoost')))),solo=G.heroes.length===1;openModal(`<div class="eyebrow">Победа</div><h2>Пепел рассеялся</h2><div class="modal-sub">Получено ${gain} золота. ${solo?'Выберите одну карту для колоды.':'Выберите карту и героя, который её возьмёт.'}</div><div class="reward-cards">${opts.map((id,i)=>`<div>${cardHTML(id,100+i)}<div style="display:flex;gap:4px;margin-top:8px">${solo?`<button class="btn gold" style="width:100%;padding:7px" onclick="takeReward('${id}',0)">Взять карту</button>`:`<button class="btn" style="padding:7px" onclick="takeReward('${id}',0)">→ Роуэн</button><button class="btn" style="padding:7px" onclick="takeReward('${id}',1)">→ Мира</button>`}</div></div>`).join('')}</div><div class="modal-actions"><button class="btn" onclick="closeModal();completeNode()">Пропустить</button></div>`)}
function takeReward(id,hero){G.heroes[hero].deck.push(id);closeModal();completeNode()}
function restEvent(){openModal(`<div class="event-art">♨</div><div class="eyebrow">Тихое место</div><h2>Костёр под сводами</h2><p class="event-text">Огонь здесь не греет, но напоминает о доме. У вас есть время только на одно решение.</p><div class="choice-grid"><button class="choice" onclick="restHeal()"><b>Отдохнуть</b><span>Оба героя восстанавливают 30% ОЗ.</span></button><button class="choice" onclick="upgradeRandom()"><b>Закалить карты</b><span>Добавить каждому герою по мощной карте.</span></button><button class="choice" onclick="gainRespec()"><b>Переосмыслить путь</b><span>Получить одну точку возврата последнего узла.</span></button></div>`)}
function restHeal(){let br=Math.max(0,...G.heroes.map(h=>metaStat(h.kind,'betterRest')));G.heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+Math.ceil(h.maxHp*(.3+.08*br))));closeModal();completeNode()}
function gainRespec(){G.respecs=(G.respecs||0)+1;closeModal();completeNode()}
function upgradeRandom(){G.heroes.forEach(h=>{let pool=CLASS_CARDS[h.kind].filter(id=>['rare','legendary'].includes(getCard(id).rarity));h.deck.push(pool[Math.floor(rng()*pool.length)])});closeModal();completeNode()}
function storyEvent(){let evts=[merchantEvent,smithEvent,tombEvent];evts[Math.floor(rng()*evts.length)]()}
function merchantEvent(){let paid=G.gold>=35;openModal(`<div class="event-art">🕯️</div><div class="eyebrow">Событие</div><h2>Торговец воспоминаниями</h2><p class="event-text">Слепой человек предлагает флакон с вашим общим воспоминанием. «Вы уже были здесь, — шепчет он. — Просто забыли».</p><div class="choice-grid"><button class="choice" ${paid?'':'disabled'} onclick="buyRelic()"><b>Купить флакон · 35 золота</b><span>Максимум ОЗ обоих героев +8, полностью исцелить.</span></button><button class="choice" onclick="eventLeave()"><b>Пройти мимо</b><span>Сохранить золото и продолжить путь.</span></button></div>`)}
function smithEvent(){openModal(`<div class="event-art">🔨</div><div class="eyebrow">Событие</div><h2>Кузнец пепла</h2><p class="event-text">Сгорбленный кузнец гасит горн. «Колода тяжелеет от лишнего, — говорит он. — Могу убрать одну карту. Бесплатно: мне нужен только металл воспоминаний».</p><div class="choice-grid"><button class="choice" onclick="pickTrimHero()"><b>Отдать карту</b><span>Навсегда удалить одну карту из колоды героя.</span></button><button class="choice" onclick="eventLeave()"><b>Пройти мимо</b><span>Колода остаётся как есть.</span></button></div>`)}
function pickTrimHero(){openModal(`<div class="eyebrow">Кузнец пепла</div><h2>Чья колода?</h2><div class="choice-grid">${G.heroes.map((h,j)=>`<button class="choice" onclick="showTrimDeck(${j})"><b>${esc(h.name)}</b><span>${h.deck.length} карт</span></button>`).join('')}</div><div class="modal-actions"><button class="btn" onclick="eventLeave()">Никакую</button></div>`)}
function showTrimDeck(j){let h=G.heroes[j],counts={};h.deck.forEach(id=>counts[id]=(counts[id]||0)+1);let items=Object.entries(counts).map(([id,n])=>{let c=getCard(id);return `<button class="choice" onclick="applyTrim(${j},'${id}')"><b>${esc(c.name)}${n>1?' ×'+n:''}</b><span>${(c.tags||[]).join(' · ')||c.type}</span></button>`}).join('');openModal(`<div class="eyebrow">${esc(h.name)}</div><h2>Какую карту убрать?</h2><div class="choice-grid">${items}</div><div class="modal-actions"><button class="btn" onclick="eventLeave()">Никакую</button></div>`)}
function applyTrim(j,id){let h=G.heroes[j],k=h.deck.indexOf(id);if(k>=0)h.deck.splice(k,1);toast('Карта отдана кузнецу');saveRun();closeModal();completeNode()}
function tombEvent(){openModal(`<div class="event-art">⚰️</div><div class="eyebrow">Событие</div><h2>Тихая гробница</h2><p class="event-text">В раскрытом саркофаге шуршит золото. Что-то внутри терпеливо ждёт, когда вы протянете руку.</p><div class="choice-grid"><button class="choice" onclick="tombTake()"><b>Запустить руку</b><span>+90 золота. Самый здоровый герой теряет 12 ОЗ, но выживет.</span></button><button class="choice" onclick="eventLeave()"><b>Пройти мимо</b><span>Не искушать пепел.</span></button></div>`)}
function tombTake(){G.gold+=90;let t=[...G.heroes].sort((a,b)=>b.hp/b.maxHp-a.hp/a.maxHp)[0];t.hp=Math.max(1,t.hp-12);toast('+90 золота');saveRun();closeModal();completeNode()}
function shopEvent(){window._shopBought=[];window._shopOpts=null;renderShop()}
function renderShop(){let pool=[...REWARDS,...G.heroes.flatMap(h=>CLASS_CARDS[h.kind]||[])];let bought=window._shopBought||[];let opts=window._shopOpts||(window._shopOpts=rollCardRewards(pool,4));let price=c=>({common:45,uncommon:65,rare:90,legendary:130})[c.rarity||'common'];let cards=opts.map((id,i)=>{let c=getCard(id),p=price(c),sold=bought.includes(id);return `<div>${cardHTML(id,200+i,true)}<button class="btn gold" style="width:100%;padding:7px;margin-top:8px" ${sold||G.gold<p?'disabled':''} onclick="buyShopCard('${id}')">${sold?'Продано':p+' зол.'}</button></div>`}).join('');openModal(`<div class="eyebrow">Торговая точка</div><h2>Пепельный рынок</h2><p class="modal-sub">Золото: <b>${G.gold}</b>. Нажмите кнопку под картой, чтобы купить её в колоду героя.</p><div class="reward-cards">${cards}</div><div class="modal-actions"><button class="btn" ${G.gold<30?'disabled':''} onclick="healAtShop()">Перевязочный набор · 30 зол. (+18 ОЗ всем)</button><button class="btn" onclick="closeModal();completeNode()">Уйти с рынка</button></div>`)}
function buyShopCard(id){let bought=window._shopBought||[];let c=getCard(id),p=({common:45,uncommon:65,rare:90,legendary:130})[c.rarity||'common'];if(bought.includes(id)||G.gold<p){toast('Недоступно');return}if(G.heroes.length===1){payShop(id,0);return}openModal(`<div class="eyebrow">Покупка</div><h2>${esc(c.name)} · ${p} зол.</h2><p class="modal-sub">Кому положить карту в колоду?</p><div class="choice-grid">${G.heroes.map((h,j)=>`<button class="choice" onclick="payShop('${id}',${j})"><b>→ ${esc(h.name)}</b><span>${h.deck.length} карт</span></button>`).join('')}</div><div class="modal-actions"><button class="btn" onclick="renderShop()">Назад</button></div>`)}
function payShop(id,j){let c=getCard(id),p=({common:45,uncommon:65,rare:90,legendary:130})[c.rarity||'common'];if(G.gold<p)return;G.gold-=p;G.heroes[j].deck.push(id);(window._shopBought??=[]).push(id);toast('Куплено: '+c.name);saveRun();renderShop()}
function healAtShop(){if(G.gold<30)return;G.gold-=30;G.heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+18));toast('Отряд перевязан');saveRun();renderShop()}
function restEvent(){openModal(`<div class="event-art">♨</div><div class="eyebrow">Тихое место</div><h2>Костёр под сводами</h2><p class="event-text">Огонь здесь не греет, но напоминает о доме. У вас есть время только на одно решение.</p><div class="choice-grid"><button class="choice" onclick="restHeal()"><b>Отдохнуть</b><span>Оба героя восстанавливают 30% ОЗ.</span></button><button class="choice" onclick="offerUpgrade()"><b>Закалить карту</b><span>Выбранная карта будет стоить на 1 меньше.</span></button><button class="choice" onclick="upgradeRandom()"><b>Пополнить колоду</b><span>Добавить каждому герою по мощной карте.</span></button><button class="choice" onclick="gainRespec()"><b>Переосмыслить путь</b><span>Получить одну точку возврата последнего узла.</span></button></div>`)}
function offerUpgrade(){openModal(`<div class="eyebrow">Привал</div><h2>Закалить карту</h2><p class="modal-sub">Выберите героя. Закалённая карта стоит на 1 меньше — навсегда.</p><div class="choice-grid">${G.heroes.map((h,j)=>`<button class="choice" onclick="pickUpgradeHero(${j})"><b>${esc(h.name)}</b><span>${h.deck.length} карт</span></button>`).join('')}</div><div class="modal-actions"><button class="btn" onclick="restEvent()">Назад</button></div>`)}
function pickUpgradeHero(j){let h=G.heroes[j],counts={};h.deck.forEach(id=>counts[id]=(counts[id]||0)+1);let items=Object.entries(counts).map(([id,n])=>{let c=getCard(id),can=c.cost>0&&!id.endsWith('+');return `<button class="choice" ${can?'':'disabled'} onclick="applyUpgrade(${j},'${id}')"><b>${esc(c.name)}${n>1?' ×'+n:''}</b><span>${can?'Стоимость: '+c.cost+' → '+(c.cost-1):'Нельзя закалить'}</span></button>`}).join('');openModal(`<div class="eyebrow">${esc(h.name)}</div><h2>Какую карту закалить?</h2><div class="choice-grid">${items}</div><div class="modal-actions"><button class="btn" onclick="offerUpgrade()">Назад</button></div>`)}
function applyUpgrade(j,id){let h=G.heroes[j],k=h.deck.indexOf(id);if(k>=0)h.deck[k]=id+'+';saveRun();toast('Карта закалена');closeModal();completeNode()}
function buyRelic(){G.gold-=35;G.relic='Общий сон';G.heroes.forEach(h=>{h.maxHp+=8;h.hp=h.maxHp});closeModal();completeNode()}
function eventLeave(){closeModal();completeNode()}
function showDeck(){if(!G)return;openModal(`<div class="eyebrow">Арсенал отряда</div><h2>Колоды героев</h2>${G.heroes.map((h,j)=>`<h3>${h.name} · ${h.deck.length} карт</h3><div class="small">${Object.entries(h.deck.reduce((a,x)=>(a[x]=(a[x]||0)+1,a),{})).map(([id,n])=>`${(getCard(id)||{icon:'🃏',name:'???'}).icon} ${(getCard(id)||{icon:'🃏',name:'???'}).name} ×${n}`).join('　')}</div>`).join('<div class="rule"></div>')}<div class="modal-actions"><button class="btn" onclick="closeModal()">Закрыть</button></div>`)}
function victory(){gainEssence(5);localStorage.removeItem('ashspire-save');openModal(`<div style="text-align:center"><div style="font-size:76px">◆</div><div class="eyebrow">Шпиль покорён</div><h2>Вы выбрались вместе</h2><p class="event-text">Сердце Печи замолкает. Впервые за тысячу лет над башней видно небо. Ваш союз оказался сильнее её голода.</p><button class="btn primary" onclick="closeModal();afterRun()">Новый забег</button></div>`)}
function afterRun(){if(G&&G.mode==='solo')soloSelect();else newRun()}function defeat(){gainEssence(1);localStorage.removeItem('ashspire-save');openModal(`<div style="text-align:center"><div style="font-size:70px">☠</div><div class="eyebrow">Забег окончен</div><h2>Шпиль забрал своё</h2><p class="event-text">Но пепел помнит ваши шаги. В следующий раз путь может сложиться иначе.</p><button class="btn primary" onclick="closeModal();afterRun()">Попробовать снова</button></div>`)}
function openModal(html){$('#modal').innerHTML=html;$('#modalBack').classList.remove('hidden')}
function closeModal(){$('#modalBack').classList.add('hidden')}
function log(s,cat){if(!B)return;cat=cat||(/урон|нанос|атак/i.test(s)?'damage':/брон|яд|кров|слаб|рок|леч|слуг|прокля/i.test(s)?'status':'system');B.log.push({text:s,cat});if(B.log.length>40)B.log.splice(0,B.log.length-40)}function toast(s){let d=document.createElement('div');d.className='toast';d.textContent=s;document.body.append(d);setTimeout(()=>d.remove(),2700)}
function floatText(t,x,y,c){let d=document.createElement('div');d.className='float';d.textContent=t;d.style.cssText=`left:${x}%;top:${y}%;color:${c}`;document.body.append(d);setTimeout(()=>d.remove(),900)}

function canAct(){return !NET.active||(NET.role==='host'?B.active===0:B.active===1)}
function heroSVG(i){let src=i===0?ART.rowan:i===1?ART.mira:ART.summoner,name=i===0?'Роуэн':i===1?'Мира':'Вейра';return `<img class="model-img hero-model" src="${src}" alt="${name}">`}
function enemySVG(type){let src=type==='boss'?ART.boss:type==='elite'?ART.elite:ART.hound;return `<img class="model-img enemy-model" src="${src}" alt="Противник">`}
function applyArenaArt(){if(!B)return;let src=B.type==='boss'?ART.sanctum:B.type==='elite'?ART.gallery:ART.lower;$('.arena').style.backgroundImage=`linear-gradient(90deg,rgba(7,9,12,.38),rgba(7,9,12,.14) 50%,rgba(7,9,12,.4)),linear-gradient(0deg,rgba(8,10,14,.72),transparent 55%),url(${src})`}



const META=(()=>{try{return JSON.parse(localStorage.getItem('ashspire-meta'))||{essence:0,skills:{1:[],2:[],3:[]}}}catch(e){return{essence:0,skills:{1:[],2:[],3:[]}}}})();if(!META.skills)META.skills={1:[],2:[],3:[]};
function makeRunTree(kind){let cx=450,cy=450,out=[{id:`r${kind}_core`,name:'Искра судьбы',desc:'Начало пути. Открывает три направления развития.',effect:{key:'core',v:1},type:'core',x:cx,y:cy,parents:[],branch:-1,cost:1}],layout=[{r:78,o:0,p:[]},{r:140,o:-.16,p:[0]},{r:140,o:.16,p:[0]},{r:205,o:-.15,p:[1]},{r:205,o:.15,p:[2]},{r:265,o:-.13,p:[3]},{r:265,o:.13,p:[4]},{r:320,o:-.11,p:[5]},{r:320,o:.11,p:[6]},{r:370,o:-.09,p:[7]},{r:405,o:.1,p:[8]}];BRANCHES[kind].forEach((br,b)=>{let base=-Math.PI/2+b*Math.PI*2/3;layout.forEach((q,j)=>{let type=j===10?'legendary':(j===7||j===8||j===9)?'keystone':(j===3||j===4)?'notable':'minor',raw=br.nodes[j],id=`r${kind}_b${b}_${j}`,parents=j===0?[`r${kind}_core`]:q.p.map(x=>`r${kind}_b${b}_${x}`),effect={key:raw[1],v:raw[2]},ang=base+q.o;out.push({id,name:raw[0],desc:effectDesc(effect,kind),effect,type,x:cx+Math.cos(ang)*q.r,y:cy+Math.sin(ang)*q.r,parents,branch:b,cost:type==='legendary'?3:type==='keystone'?2:1,color:br.color})})});return out}
function makeMetaTree(kind){let cx=410,cy=270;return META_BRANCHES[kind].map((raw,i)=>{let a=-Math.PI/2+i/8*Math.PI*2,inner=i<4,r=inner?125:230;return{id:`m${kind}_${i}`,name:raw[0],desc:metaDesc(raw[1],raw[2]),effect:{key:raw[1],v:raw[2]},type:i>=4?'notable':'minor',x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r,parent:i===0?null:i<4?`m${kind}_0`:`m${kind}_${i-4}`,branch:i%3,cost:i>=4?2:1,color:BRANCHES[kind][i%3].color}})}
function treeNodes(kind,meta=false){return meta?makeMetaTree(kind):makeRunTree(kind)}
function effectDesc(e){const d={damage:`Атаки наносят +${e.v} урона.`,block:`В начале боя получить ${e.v} брони.`,hp:`Максимум здоровья +${e.v}.`,draw:'В первом раунде взять дополнительную карту.',energy:`В первом раунде получить +${e.v} энергии.`,bleed:`Кровотечение от карт +${e.v}.`,poison:`Яд от карт +${e.v}.`,minion:`Урон каждого слуги +${e.v}.`,maxMinion:`Максимум слуг +${e.v}.`,heavyDamage:`Карты стоимостью 2+ наносят +${e.v} урона.`,healPower:`Лечение от карт +${e.v}.`,doom:`Рок от карт +${e.v}.`,thorns:`В начале боя получить ${e.v} шипов.`,retainBlock:`Сохранять ${e.v}% брони между раундами.`,counter:`При полной блокировке атаки нанести ${e.v} урона.`,lowHpDamage:`При здоровье ниже 50% атаки наносят +${e.v}.`,killHeal:`После победы восстановить ${e.v} здоровья.`,firstAttack:`Первая атака раунда наносит +${e.v}.`,comboDamage:`Каждая следующая атака за ход получает +${e.v}.`,thirdHit:`Каждая третья атака наносит ещё ${e.v}.`,weakPower:`Слабые враги наносят ещё на ${e.v} меньше урона.`,poisonBlock:`Когда яд наносит урон, получить ${e.v} брони.`,blessingPower:'Благословения комнат действуют сильнее.',overhealBlock:'Избыточное лечение превращается в броню.',firstDiscount:'Первая карта стоимостью 2+ в раунде стоит на 1 меньше.',handPower:`При руке из 5+ карт атаки наносят +${e.v}.`,summonBlock:`При призыве получить ${e.v} брони.`,sacrificeDamage:`Жертвоприношение наносит ещё ${e.v} урона.`,sacrificeEnergy:`Первая жертва раунда даёт ${e.v} энергии.`,sacrificeBlock:`Жертвоприношение даёт ${e.v} брони.`,sacrificeHeal:`Жертвоприношение лечит на ${e.v}.`,avatarWard:`Главный слуга даёт ${e.v} брони в начале раунда.`,lowHpBlock:`При здоровье ниже 50% получать ${e.v} брони в начале каждого раунда.`};if(d[e.key])return d[e.key];const traits={ironVow:'Броня не исчезает между раундами, но максимум энергии уменьшается на 1.',armorDamage:'При наличии 20+ брони атаки наносят на 20% больше урона.',livingFortress:'Защитные карты применяются дважды; атакующие стоят на 1 больше.',selfPower:'Получение урона от собственной карты даёт силу.',bloodOath:'Лечение уменьшено вдвое, бонусы при низком здоровье удвоены.',lastDrop:'Один раз за бой пережить смертельный удар с 1 здоровьем.',weaponMaster:'Третья атака каждого хода стоит 0 энергии.',doubleHeavy:'Первая тяжёлая атака раунда применяется дважды и даёт слабость.',poisonPersist:'Яд больше не уменьшается в конце раунда.',spreadPoison:'После победы яд переносится в следующий бой частично.',plagueWord:'Прямой урон ниже, но весь накладываемый яд удваивается.',poisonArmor:'Действующий яд дополнительно разрушает броню врага.',poisonBurst:'При 20+ яда немедленно активировать половину.',eternalPoison:'Яд не уменьшается и срабатывает дважды; прямой урон −30%.',cleanseBlock:'Очищение также даёт броню.',fullMoon:'Каждый третий раунд восстановить часть недавно потерянного здоровья.',allyHeal:'Лечение себя также лечит союзника.',moonRebirth:'Один раз за бой пережить смерть и восстановить 20% здоровья.',recycle:'Первая истощённая карта возвращается в сброс.',emptyRefill:'Когда рука впервые опустела, взять 3 карты.',forbidden:'Карты, взятые сверх пяти, стоят 0 до конца раунда.',autoSummon:'В начале каждого раунда призывать одного слугу.',legion:'Слуги слабее по отдельности, но их максимум удваивается.',minionLeech:'Урон слуг понемногу лечит хозяина.',endlessArmy:'Погибшие и пожертвованные слуги возвращаются в следующем раунде.',singleAvatar:'Можно иметь только одного слугу; новые призывы усиливают его.',avatarStrength:'Главный слуга получает часть силы героя.',absorbSummon:'Поглощённый призыв навсегда усиливает главного слугу в бою.',avatarGuard:'Пока у героя есть слуги, атаки по нему наносят на 2 меньше урона за узел.',perfectAvatar:'Главный слуга атакует дважды, но карты призыва стоят дороже.',avatarPoison:'Атаки главного слуги накладывают яд.',immortalAvatar:'Раз за бой, когда слуги должны погибнуть полностью, один выживает с половиной силы.',doubleSacrifice:'Эффекты первой жертвы раунда срабатывают дважды.',recycleSummon:'После жертвы вернуть случайную карту призыва из сброса.',sacrificeCircle:'После трёх жертв следующая карта бесплатна.',tripleDeath:'Эффекты жертвы срабатывают трижды; призывы стоят дороже.'};return traits[e.key]||'Меняет правила выбранного архетипа.'}
function metaDesc(k,v){return({startGold:`Начинать забег с дополнительными ${v} золотыми.`,extraChoice:'После боя иногда показывается четвёртая карта.',revealRooms:'Модификаторы боевых комнат видны на карте заранее.',startPoint:'Начинать забег с дополнительным очком древа.',freeRespec:'Один бесплатный возврат узла за забег.',rareBoost:'Шанс редких наград немного повышен.',betterRest:'Привалы восстанавливают на 8% больше здоровья за узел.',secondChance:'Один раз за забег поражение оставляет героя с 1 здоровьем.'})[k]}
const _statCache=new Map();
function skillStat(h,key){if(!h)return 0;let runIds=G?.skills||[],metaIds=META.skills[h.kind]||[],sig=h.kind+'|'+runIds.join(',')+'|'+metaIds.join(',');let m=_statCache.get(sig);if(!m){m=new Map();makeRunTree(h.kind).forEach(n=>{if(runIds.includes(n.id))m.set(n.effect.key,(m.get(n.effect.key)||0)+n.effect.v)});makeMetaTree(h.kind).forEach(n=>{if(metaIds.includes(n.id))m.set(n.effect.key,(m.get(n.effect.key)||0)+n.effect.v)});if(_statCache.size>60)_statCache.clear();_statCache.set(sig,m)}return m.get(key)||0}
function hasTrait(h,key){return skillStat(h,key)>0}
function metaStat(kind,key){return skillStat({kind},key)}
function showSkillTree(meta=false,kind=(G?.heroes?.[0]?.kind||1)){window._treeMeta=meta;window._treeKind=kind;let nodes=treeNodes(kind,meta),owned=meta?(META.skills[kind]||[]):(G.skills||[]),points=meta?META.essence:(G.skillPoints||0),byId=Object.fromEntries(nodes.map(n=>[n.id,n])),lines=nodes.flatMap(n=>(n.parents||(n.parent?[n.parent]:[])).map(pid=>{let p=byId[pid],dx=n.x-p.x,dy=n.y-p.y,l=Math.hypot(dx,dy),a=Math.atan2(dy,dx)*180/Math.PI,on=owned.includes(n.id)&&owned.includes(p.id);return `<i class="tree-line ${on?'on':''}" style="left:${p.x}px;top:${p.y}px;width:${l}px;transform:rotate(${a}deg);--branch:${n.color||'#d5aa56'}"></i>`})).join(''),btns=nodes.map(n=>{let parents=n.parents||(n.parent?[n.parent]:[]),ok=!parents.length||parents.some(x=>owned.includes(x)),state=owned.includes(n.id)?'unlocked':ok&&points>=n.cost?'available':'locked',search=(n.name+' '+n.desc).toLowerCase();return `<button data-search="${search}" class="skill-node ${state} ${n.type}" style="left:${n.x}px;top:${n.y}px;--node-color:${n.color||'#e0ad55'}" onclick="unlockSkill('${n.id}')">${skillIcon(kind,n.id,n.type,n.color)}<span class="skill-tip"><b>${n.name}</b><small>${n.type==='legendary'?'ЛЕГЕНДАРНЫЙ':n.type==='keystone'?'КЛЮЧЕВОЙ':n.type==='notable'?'ЗНАЧИМЫЙ':'ПАССИВНЫЙ'}</small><br>${n.desc}${n.branch>=0?`<br><span style="color:#999">Затрагивает: ${BRANCHES[kind][n.branch].cards}</span>`:''}<br><em>Стоимость: ${n.cost}</em></span></button>`}).join(''),summary=!meta?BRANCHES[kind].map((b,i)=>`<span style="color:${b.color}"><b>${b.name}</b> · ${nodes.filter(n=>n.branch===i&&owned.includes(n.id)).length}</span>`).join('　'):'';openModal(`<div class="eyebrow">Пассивная сеть · ${esc(G.heroes.find(h=>h.kind===kind)?.name||['','Роуэн','Мира','Вейра'][kind])}</div><h2>${meta?'Наследие':'Созвездие судьбы'}</h2><div class="tree-tabs"><button class="btn ${!meta?'gold':''}" onclick="showSkillTree(false,${kind})">Забег · ${G.skillPoints||0} очк.</button><button class="btn ${meta?'gold':''}" onclick="showSkillTree(true,${kind})">Наследие · ${META.essence} эсс.</button>${G.heroes.length>1?G.heroes.map(h=>`<button class="btn" onclick="showSkillTree(${meta},${h.kind})">${esc(h.name)}</button>`).join(''):''}</div><div class="tree-toolbar"><input placeholder="Найти: яд, броня, слуги…" oninput="filterSkillNodes(this.value)"><button class="btn" onclick="refundLastSkill()">↶ Вернуть последний · ${G.respecs||0}</button></div><div class="tree-summary">${summary}</div><div class="tree-shell"><div class="tree-canvas ${meta?'meta-tree':''}">${lines}${btns}</div></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Закрыть</button></div>`);setTimeout(()=>{let t=$('.tree-shell');if(t){t.scrollLeft=90;t.scrollTop=120}},0)}
function unlockSkill(id){let meta=id[0]==='m',kind=+id[1],nodes=treeNodes(kind,meta),n=nodes.find(x=>x.id===id),owned=meta?(META.skills[kind]||[]):G.skills;if(!n||owned.includes(id))return;let parents=n.parents||(n.parent?[n.parent]:[]),ok=!parents.length||parents.some(x=>owned.includes(x)),points=meta?META.essence:G.skillPoints;if(!ok||points<n.cost){playSfx('error');return}owned.push(id);if(meta){META.essence-=n.cost;localStorage.setItem('ashspire-meta',JSON.stringify(META))}else{G.skillPoints-=n.cost;(G.skillHistory??=[]).push(id);applyImmediateSkill(n,kind)}playSfx('win');saveRun();showSkillTree(meta,kind)}
function applyImmediateSkill(n,kind){let h=G.heroes.find(x=>x.kind===kind);if(!h)return;if(n.effect.key==='hp'){h.maxHp+=n.effect.v;h.hp+=n.effect.v}}
function refundLastSkill(){if(window._treeMeta){toast('Узлы Наследия постоянны');return}if((G.respecs||0)<=0){toast('Нужна точка пересмотра с привала');return}let id=(G.skillHistory||[]).pop();if(!id){toast('Нет узлов для возврата');return}let n=makeRunTree(window._treeKind).find(x=>x.id===id);if(!n){toast('Последний узел принадлежит другому герою');G.skillHistory.push(id);return}G.skills=G.skills.filter(x=>x!==id);G.skillPoints+=n.cost;G.respecs--;let h=G.heroes.find(x=>x.kind===window._treeKind);if(h&&n.effect.key==='hp'){h.maxHp-=n.effect.v;h.hp=Math.min(h.hp,h.maxHp)}saveRun();showSkillTree(false,window._treeKind)}
function filterSkillNodes(q){q=q.toLowerCase().trim();$$('.skill-node').forEach(n=>n.style.opacity=!q||n.dataset.search.includes(q)?'':'0.12')}
function gainEssence(n){META.essence+=n;localStorage.setItem('ashspire-meta',JSON.stringify(META))}
function skillIcon(kind,id,type,color){if(typeof SKILL_ART!=='undefined'&&SKILL_ART[id])return `<img class="ai-skill-art" src="${SKILL_ART[id]}" alt="Навык">`;let seed=[...id].reduce((a,c)=>a+c.charCodeAt(0),0),h=(seed*47+kind*80)%360,c=color||`hsl(${h} 70% 58%)`,shape=type==='legendary'?'M25 4L31 19 47 20 35 31 39 47 25 38 11 47 15 31 3 20 19 19Z':type==='keystone'?'M25 5L44 16V36L25 47 6 36V16Z':'M25 8L31 20 44 25 31 30 25 43 19 30 6 25 19 20Z';return `<svg viewBox="0 0 50 50"><defs><radialGradient id="g${seed}"><stop stop-color="${c}"/><stop offset="1" stop-color="#17141d"/></radialGradient></defs><circle cx="25" cy="25" r="22" fill="url(#g${seed})"/><path d="${shape}" fill="none" stroke="#fff" opacity=".9" stroke-width="2"/></svg>`}
function generatedArt(seed,type){let h=(seed*67)%360,h2=(h+70)%360,shape=seed%3===0?'M10 54L35 8 60 54Z':seed%3===1?'M12 32Q35 2 58 32T12 32':'M35 7L61 32 35 59 9 32Z';return `<svg class="generated-art" viewBox="0 0 70 64"><defs><radialGradient id="a${seed}"><stop stop-color="hsl(${h} 75% 58%)"/><stop offset="1" stop-color="hsl(${h2} 60% 12%)"/></radialGradient></defs><rect width="70" height="64" fill="url(#a${seed})"/><circle cx="35" cy="32" r="24" fill="none" stroke="#fff" opacity=".16"/><path d="${shape}" fill="none" stroke="#f8edcf" stroke-width="3"/><path d="M8 ${12+seed%25}H62M${12+seed%30} 7L${50-seed%20} 58" stroke="#fff" opacity=".13"/></svg>`}
function rarityName(r){return ({common:'обычная',uncommon:'необычная',rare:'редкая',legendary:'легендарная'})[r]||''}
function rollCardRewards(pool,count=3,boost=0){let weighted=[];pool.forEach(id=>{let r=getCard(id)?.rarity||'common',w={common:Math.max(3,7-boost),uncommon:4,rare:2+boost,legendary:1+boost}[r];for(let i=0;i<w;i++)weighted.push(id)});let out=[];while(out.length<count&&weighted.length){let id=weighted[Math.floor(rng()*weighted.length)];weighted=weighted.filter(x=>x!==id);if(getCard(id)&&!out.includes(id))out.push(id)}return out}
function rollRoomMod(){if(rng()>.55)return null;return {...ROOM_MODS[Math.floor(rng()*ROOM_MODS.length)]}}
